package com.vibeguard.samples.invoices; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.*; import java.util.concurrent.ConcurrentHashMap; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Generates invoices and enforces configured owner-only access. */ @RestController @RequestMapping("/api/invoices") public class InvoiceController { private final Map<String,Invoice> invoices=new ConcurrentHashMap<>(); @Value("${INVOICE_OWNER_KEY:}") private String key; @Value("${INVOICE_OWNER_ID:}") private String owner; @PostMapping public ResponseEntity<Invoice> create(@RequestHeader("X-Invoice-Owner-Key") String supplied,@Valid @RequestBody Request request){if(!allowed(supplied,request.customerId()))return ResponseEntity.status(403).build();Invoice invoice=new Invoice(UUID.randomUUID().toString(),request.customerId(),request.amount(),"OPEN");invoices.put(invoice.id(),invoice);return ResponseEntity.status(201).body(invoice);}@GetMapping("/{id}") public ResponseEntity<Invoice> get(@RequestHeader("X-Invoice-Owner-Key") String supplied,@PathVariable String id){Invoice invoice=invoices.get(id);if(invoice==null)return ResponseEntity.notFound().build();return allowed(supplied,invoice.customerId())?ResponseEntity.ok(invoice):ResponseEntity.status(403).build();}private boolean allowed(String supplied,String customer){return !key.isBlank()&&key.equals(supplied)&&owner.equals(customer);}record Request(@NotBlank String customerId,@Positive long amount){}record Invoice(String id,String customerId,long amount,String status){} }
